head.script:
scwin.screenId = "jldinf30001";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = async function () {
    const attrRealsList = [{ childId: "td_51", attr: "__html", fn: function () { return ([String(String(String(dma_map.get("regContnContn"))).split("\\\\n").join("<br/>"))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? (String(String(String(dma_map.get("regContnContn"))).split("\\\\n").join("<br/>"))) : ''); } }];
    const root = (function () { try { const f = $c.win.getFrame(); return (f && f.render) ? f.render : null; } catch (e) { return null; } })();
    const hasText = function (t) { return /[가-힣A-Za-z0-9]/.test(String(t == null ? "" : t)); };
    let applied = 0;
    for (let i = 0; i < attrRealsList.length; i++) {
        const a = attrRealsList[i];
        const comp = $c.util.getComponent(a.childId);
        const el = (comp && comp.getID && root) ? root.querySelector("#" + comp.getID()) : null;
        if (!comp && !el) { console.warn("[sdd] 속성 실현 대상 부재: " + a.childId); continue; }
        let v;
        try { v = a.fn(); } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId + "." + a.attr }); continue; }
        if (a.attr === "style") {
            if (comp && typeof comp.setStyle === "function") {
                const decls = String(v).split(";");
                for (let di = 0; di < decls.length; di++) {
                    const kv = decls[di].split(":");
                    if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
                }
            } else if (el) { el.style.cssText = (el.style.cssText || "") + ";" + v; }
        } else if (a.attr === "label") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); } else if (el) { el.textContent = v; }
        } else if (a.attr === "__value") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); }
        } else if (a.attr === "__items") {
            if (comp && typeof comp.addItem === "function" && v && v.length) {
                let hasVal = false;
                for (let ii = 0; ii < v.length; ii++) { if (hasText(v[ii][0]) || hasText(v[ii][1])) { hasVal = true; break; } }
                if (hasVal) {
                    if (typeof comp.removeAll === "function") { comp.removeAll(); }
                    for (let ij = 0; ij < v.length; ij++) {
                        const lb = String(v[ij][1] || "");
                        comp.addItem(String(v[ij][0] || ""), hasText(lb) ? lb : "");
                    }
                }
            }
        } else if (a.attr === "class") {
            if (el) { el.className = v; }
        } else if (a.attr === "__html") {
            if (el && !el.querySelector('[class*="w2"], input, select, textarea, button')) { el.innerHTML = v; }
        } else if (el) {
            el.setAttribute(a.attr, v);
            if (a.attr === "src" && el.tagName === "IMG") { el.src = v; }
        }
        applied++;
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_contnId", fn: function () { return String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("contnId"))); } },
        { childId: "__rb0", fn: function () { return String(String(String(dma_map.get("contnTitle"))).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_goList();
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.dmenus = undefined; try { scwin.dmenus = /* sdd-asis-lifecycle:begin dmenus — as-is 원문 본문(전환 이관 · 포팅 적용됨) */{
        "bmenu":5
        ,"mmenu":1
    }/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf30001' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_attrReals();
        await scwin.init_loadList();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf30001.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.td_32_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.td_32_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try { if (columnId === 'attachFileNm') { const d = $c.util.getComponent('dlt_fileResult'); if (!d) { return; } if (typeof scwin.downloadFile === 'function') { await scwin.downloadFile(String(d.getCellData(rowIndex, "contnId")), String(d.getCellData(rowIndex, "attachFileNo"))); } else { console.error('[sdd] 행 동작 미정의: scwin.downloadFile (열 attachFileNm)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.downloadFile'); } return; } 
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf30001.td_32_oncellclick' }); }
};

/**
 * @event
 * @name scwin.td_32_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.td_32_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_fileResult');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_fileResult'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.downloadFile === 'function') { await scwin.downloadFile(r["contnId"], r["attachFileNo"]); } else { console.error('[sdd] 행 동작 미정의: scwin.downloadFile (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.downloadFile'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'td_32.oncellclick' });
    }
};

/**
 * @event
 * @name scwin.btn_goList_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_goList_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_goList_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.goList()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf30001.btn_goList_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_downloadFile
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_downloadFile = async function () {
    try { return await $c.data.downFile("/info/noticeDownload.do", "", ($c.util.getComponent("dma_downloadFileReq") ? $c.util.getComponent("dma_downloadFileReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name scwin.tx_goList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_goList = async function () {
    const sbmOptions = {
        id: "tx_goList",
        method: "post",
        action: "/info/notice.do?method=noticeList",
        ref: "dma_goListReq",
        target: "dlt_fileResult=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldinf30001.tx_goList" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.td_32_fmt_attachFileNm
 * @author Inswave
 * @date 2026. 09. 29
 * @param data formattedData rowIndex columnIndex
 * @returns
 * @hidden N
*/
scwin.td_32_fmt_attachFileNm = function (data, formattedData, rowIndex, columnIndex) { return '<a href="javascript:void(0)"><strong>' + String(data) + '</strong></a>'; };

/**
 * @method
 * @name scwin.downloadFile
 * @author Inswave
 * @date 2026. 09. 29
 * @param contn_id attach_file_no
 * @returns
 * @hidden N
*/
scwin.downloadFile = async function (contn_id, attach_file_no) {
    /* sdd-asis-lifecycle:begin downloadFile — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const obj = (document.downloadForm || { elements: [] });
    obj.action = '/info/noticeDownload.do';
    $c.util.getComponent('dma_downloadFileReq').set('method', 'noticeDownload');
    $c.util.getComponent("dma_downloadFileReq").set("contnId", contn_id);
    $c.util.getComponent("dma_downloadFileReq").set("attachFileNo", attach_file_no);
    await scwin.tx_downloadFile();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.goList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.goList = async function () {
    /* sdd-asis-lifecycle:begin goList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const form = (document.JLDINF30001 || { elements: [] });
    form.action = "/info/notice.do?method=noticeList";
    await scwin.tx_goList();
    /* sdd-asis-lifecycle:end */
};
